/// <summary>
/// Controller class that orchestrates the con demo job history scan operation.
/// </summary>
public class ConDemoJobHistoryScanController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Constructs a controller wired to the scan service.
/// </summary>
/// <returns>The constructed controller.</returns>
public static ConDemoJobHistoryScanController construct()
{
    ConDemoJobHistoryScanController controller = new ConDemoJobHistoryScanController();

    controller.parmClassName(classStr(ConDemoJobHistoryScanService));
    controller.parmMethodName(methodStr(ConDemoJobHistoryScanService, scanHistory));

    return controller;
}

/// <summary>
/// Entry point of the batch job.
/// </summary>
/// <param name = "_args">The arguments of the caller.</param>
public static void main(Args _args)
{
    ConDemoJobHistoryScanController controller = ConDemoJobHistoryScanController::construct();

    controller.parmArgs(_args);
    controller.parmDialogCaption("@ConDemo:JobHistoryScanCaption");
    controller.startOperation();
}
